messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Red vs Blue — Drag Race</title>
<style>
  html, body { margin: 0; padding: 0; overflow: hidden; background: #87b6d8; }
  canvas { display: block; }
  #hud {
    position: fixed; top: 16px; left: 50%; transform: translateX(-50%);
    font-family: 'Courier New', monospace; font-size: 22px; font-weight: bold;
    color: #ffffff; text-shadow: 0 2px 4px rgba(0,0,0,0.6);
    letter-spacing: 2px; z-index: 10; pointer-events: none;
  }
  #hud .red { color: #ff2a2a; }
  #hud .blue { color: #2a6bff; }
</style>
</head>
<body>
<div id="hud"><span class="blue">BLUE</span> vs <span class="red">RED</span> — DRAG RACE</div>
<script type="module">
import * as THREE from './three.module.js';

// ---------- Renderer / Scene ----------
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87b6d8);
scene.fog = new THREE.Fog(0x87b6d8, 180, 420);

const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 1000);

// ---------- Lights ----------
const hemi = new THREE.HemisphereLight(0xcfe8ff, 0x3a5a3a, 0.9);
scene.add(hemi);
const sun = new THREE.DirectionalLight(0xfff4e0, 1.4);
sun.position.set(-60, 90, 50);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -80;
sun.shadow.camera.right = 80;
sun.shadow.camera.top = 220;
sun.shadow.camera.bottom = -20;
sun.shadow.camera.far = 300;
scene.add(sun);

// ---------- Ground ----------
const groundGeo = new THREE.PlaneGeometry(600, 1200);
const groundMat = new THREE.MeshLambertMaterial({ color: 0x4d7c46 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.z = -300;
ground.receiveShadow = true;
scene.add(ground);

// ---------- Track ----------
const TRACK_W = 22;
const RACE_LEN = 240;      // finish line at z = -240
const FINISH_Z = -RACE_LEN;
const trackGeo = new THREE.PlaneGeometry(TRACK_W, RACE_LEN + 120);
const trackMat = new THREE.MeshLambertMaterial({ color: 0x33363b });
const track = new THREE.Mesh(trackGeo, trackMat);
track.rotation.x = -Math.PI / 2;
track.position.set(0, 0.02, -(RACE_LEN + 120) / 2 + 60);
track.receiveShadow = true;
scene.add(track);

// Lane divider dashes (looping illusion handled by race reset)
const dashMat = new THREE.MeshBasicMaterial({ color: 0xf5f5f5 });
const dashGeo = new THREE.PlaneGeometry(0.5, 5);
for (let z = -10; z > FINISH_Z; z -= 12) {
  const dash = new THREE.Mesh(dashGeo, dashMat);
  dash.rotation.x = -Math.PI / 2;
  dash.position.set(0, 0.03, z);
  scene.add(dash);
}

// Edge lines
const edgeMat = new THREE.MeshBasicMaterial({ color: 0xeeeeee });
[-TRACK_W / 2 + 0.6, TRACK_W / 2 - 0.6].forEach(x => {
  const line = new THREE.Mesh(new THREE.PlaneGeometry(0.6, RACE_LEN), edgeMat);
  line.rotation.x = -Math.PI / 2;
  line.position.set(x, 0.03, -RACE_LEN / 2);
  scene.add(line);
});

// ---------- Finish line ----------
const finishGroup = new THREE.Group();
const checkerCanvas = document.createElement('canvas');
checkerCanvas.width = 64; checkerCanvas.height = 8;
const ctx = checkerCanvas.getContext('2d');
for (let i = 0; i < 8; i++) for (let j = 0; j < 64; j++) {
  ctx.fillStyle = ((i + j) % 2 === 0) ? '#ffffff' : '#111111';
  ctx.fillRect(j, i, 1, 1);
}
const checkerTex = new THREE.CanvasTexture(checkerCanvas);
checkerTex.magFilter = THREE.NearestFilter;
const finishStrip = new THREE.Mesh(
  new THREE.PlaneGeometry(TRACK_W, 4),
  new THREE.MeshBasicMaterial({ map: checkerTex })
);
finishStrip.rotation.x = -Math.PI / 2;
finishStrip.position.set(0, 0.05, 0);
finishGroup.add(finishStrip);

// Finish gantry
const postMat = new THREE.MeshLambertMaterial({ color: 0xdddddd });
const postGeo = new THREE.BoxGeometry(0.8, 10, 0.8);
[-TRACK_W / 2, TRACK_W / 2].forEach(x => {
  const post = new THREE.Mesh(postGeo, postMat);
  post.position.set(x, 5, 0);
  post.castShadow = true;
  finishGroup.add(post);
});
const bannerCanvas = document.createElement('canvas');
bannerCanvas.width = 512; bannerCanvas.height = 64;
const bctx = bannerCanvas.getContext('2d');
bctx.fillStyle = '#1a1a1a'; bctx.fillRect(0, 0, 512, 64);
bctx.fillStyle = '#ff2a2a'; bctx.fillRect(0, 0, 256, 64);
bctx.fillStyle = '#2a6bff'; bctx.fillRect(256, 0, 256, 64);
bctx.fillStyle = '#ffffff'; bctx.font = 'bold 40px Courier New';
bctx.textAlign = 'center'; bctx.textBaseline = 'middle';
bctx.fillText('FINISH', 256, 34);
const bannerTex = new THREE.CanvasTexture(bannerCanvas);
const banner = new THREE.Mesh(
  new THREE.PlaneGeometry(TRACK_W, 3),
  new THREE.MeshBasicMaterial({ map: bannerTex, side: THREE.DoubleSide })
);
banner.position.set(0, 8.4, 0);
finishGroup.add(banner);
finishGroup.position.z = FINISH_Z;
scene.add(finishGroup);

// ---------- Car factory ----------
function makeCar(colorHex) {
  const g = new THREE.Group();
  const bodyMat = new THREE.MeshPhongMaterial({ color: colorHex, shininess: 90, specular: 0x888888 });

  // Main body
  const body = new THREE.Mesh(new THREE.BoxGeometry(2.4, 0.9, 5.2), bodyMat);
  body.position.y = 0.85;
  body.castShadow = true;
  g.add(body);

  // Cabin
  const cabin = new THREE.Mesh(new THREE.BoxGeometry(1.9, 0.75, 2.4), bodyMat);
  cabin.position.set(0, 1.6, -0.3);
  cabin.castShadow = true;
  g.add(cabin);

  // Windshield
  const glassMat = new THREE.MeshPhongMaterial({ color: 0x223344, shininess: 120, specular: 0xffffff });
  const windshield = new THREE.Mesh(new THREE.BoxGeometry(1.7, 0.6, 0.15), glassMat);
  windshield.position.set(0, 1.62, 0.95);
  windshield.rotation.x = -0.45;
  g.add(windshield);

  // Spoiler
  const spoiler = new THREE.Mesh(new THREE.BoxGeometry(2.3, 0.12, 0.6), bodyMat);
  spoiler.position.set(0, 1.75, -2.5);
  spoiler.castShadow = true;
  g.add(spoiler);
  [-0.9, 0.9].forEach(x => {
    const strut = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.5, 0.15), bodyMat);
    strut.position.set(x, 1.5, -2.5);
    g.add(strut);
  });

  // Wheels
  const wheelGeo = new THREE.CylinderGeometry(0.55, 0.55, 0.45, 20);
  const wheelMat = new THREE.MeshPhongMaterial({ color: 0x151515, shininess: 30 });
  const hubGeo = new THREE.CylinderGeometry(0.28, 0.28, 0.48, 12);
  const hubMat = new THREE.MeshPhongMaterial({ color: 0xbbbbbb, shininess: 100 });
  const wheels = [];
  const wheelPos = [[-1.25, 1.7], [1.25, 1.7], [-1.25, -1.7], [1.25, -1.7]];
  wheelPos.forEach(([x, z]) => {
    const w = new THREE.Mesh(wheelGeo, wheelMat);
    w.rotation.z = Math.PI / 2;
    w.position.set(x, 0.55, z);
    w.castShadow = true;
    const hub = new THREE.Mesh(hubGeo, hubMat);
    hub.rotation.z = Math.PI / 2;
    hub.position.set(x * 1.02, 0.55, z);
    w.add(hub);
    g.add(w);
    wheels.push(w);
  });

  // Headlights
  const lightMat = new THREE.MeshBasicMaterial({ color: 0xfff2b0 });
  [-0.75, 0.75].forEach(x => {
    const l = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.2, 0.1), lightMat);
    l.position.set(x, 0.95, 2.62);
    g.add(l);
  });
  // Taillights
  const tailMat = new THREE.MeshBasicMaterial({ color: 0xff2200 });
  [-0.75, 0.75].forEach(x => {
    const t = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.18, 0.1), tailMat);
    t.position.set(x, 1.0, -2.62);
    g.add(t);
  });

  g.userData.wheels = wheels;
  return g;
}

const LANE_X = 4.5;
const redCar = makeCar(0xff1a1a);
const blueCar = makeCar(0x1a5aff);
redCar.position.set(-LANE_X, 0, 0);
blueCar.position.set(LANE_X, 0, 0);
scene.add(redCar, blueCar);

// ---------- Race logic ----------
// Phase timeline (seconds):
// 0.0–1.2  countdown "READY... GO"
// 1.2–4.5  blue leads (fast start, then eases)
// 4.5–8.0  red accelerates hard, closes gap
// ~8.5     red overtakes
// ~10.5    red crosses finish, wins
// 11.5     reset & loop
const PHASES = { READY: 1.2, BLUE_LEAD: 3.3, RED_CHARGE: 3.5, FINISH_HOLD: 1.8 };
const T_READY = PHASES.READY;
const T_BLUE = T_READY + PHASES.BLUE_LEAD;          // 4.5
const T_CHARGE = T_BLUE + PHASES.RED_CHARGE;        // 8.0
const T_FINISH = T_CHARGE + PHASES.FINISH_HOLD;     // 9.8
const T_RESET = T_FINISH + 1.6;                     // 11.4

function easeOutCubic(t) { return 1 - Math.pow(1 - t, 3); }
function easeInCubic(t) { return t * t * t; }

function computeZ(t) {
  if (t < T_READY) return 0;
  if (t < T_BLUE) {
    // Blue: strong launch, decelerating pace
    const p = (t - T_READY) / PHASES.BLUE_LEAD;
    return -RACE_LEN * 0.42 * easeOutCubic(p);
  }
  if (t < T_CHARGE) {
    // Blue continues steadily; red launches late but hard
    const pB = (t - T_READY) / (T_CHARGE - T_READY);
    const blueZ = -RACE_LEN * (0.42 + 0.36 * easeOutCubic(pB * 0.92));
    const pR = (t - T_BLUE) / PHASES.RED_CHARGE;
    const redZ = -RACE_LEN * 0.40 * easeInCubic(pR) * 1.05;
    return { blueZ, redZ };
  }
  if (t < T_FINISH) {
    // Both sprint to the line; red ahead
    const p = (t - T_CHARGE) / PHASES.FINISH_HOLD;
    const blueStart = -RACE_LEN * (0.42 + 0.36 * easeOutCubic(0.92));
    const redStart = -RACE_LEN * 0.40 * 1.05;
    const blueZ = blueStart + (FINISH_Z - blueStart) * easeOutCubic(p) * 0.97;
    const redZ = redStart + (FINISH_Z - redStart) * easeOutCubic(p);
    return { blueZ, redZ };
  }
  // After finish: red keeps rolling a bit, blue coasts
  const p = Math.min((t - T_FINISH) / 1.4, 1);
  const redZ = FINISH_Z - 14 * easeOutCubic(p);
  const blueZ = FINISH_Z + 7 - 10 * easeOutCubic(p);
  return { blueZ, redZ };
}

// ---------- Camera follow ----------
const camPos = new THREE.Vector3(0, 14, 26);
const camLook = new THREE.Vector3(0, 1.5, -12);

function updateCamera(t, redZ, blueZ) {
  const leadZ = Math.min(redZ, blueZ); // most advanced car (most negative z)
  const targetZ = leadZ + 24;
  const targetY = 13 + Math.sin(t * 0.7) * 0.8;
  const targetX = Math.sin(t * 0.5) * 4;
  camPos.lerp(new THREE.Vector3(targetX, targetY, targetZ), 0.06);
  const lookTarget = new THREE.Vector3(0, 1.5, leadZ - 10);
  camLook.lerp(lookTarget, 0.08);
  camera.position.copy(camPos);
  camera.lookAt(camLook);
}

// ---------- HUD ----------
const hud = document.getElementById('hud');
function updateHUD(t, redZ, blueZ) {
  let msg;
  if (t < T_READY) {
    msg = 'GET READY...';
  } else if (t < T_FINISH) {
    const leader = redZ < blueZ ? '<span class="red">RED LEADS</span>' : '<span class="blue">BLUE LEADS</span>';
    msg = leader;
  } else {
    msg = '<span class="red">RED WINS!</span> — restarting...';
  }
  hud.innerHTML = msg;
}

// ---------- Animation loop ----------
const clock = new THREE.Clock();
let raceT = 0;

function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);
  raceT += dt;
  if (raceT > T_RESET) raceT = 0;

  const z = computeZ(raceT);
  let redZ, blueZ;
  if (typeof z === 'number') {
    redZ = z; blueZ = z;
  } else {
    redZ = z.redZ; blueZ = z.blueZ;
  }

  redCar.position.z = redZ;
  blueCar.position.z = blueZ;

  // Spin wheels based on speed
  const redSpeed = Math.abs(redZ - (redCar.userData.prevZ ?? redZ));
  const blueSpeed = Math.abs(blueZ - (blueCar.userData.prevZ ?? blueZ));
  redCar.userData.prevZ = redZ;
  blueCar.userData.prevZ = blueZ;
  redCar.userData.wheels.forEach(w => w.rotation.x -= redSpeed * 2.2);
  blueCar.userData.wheels.forEach(w => w.rotation.x -= blueSpeed * 2.2);

  // Slight body lean under acceleration
  redCar.rotation.x = THREE.MathUtils.clamp((redZ - (redCar.userData.pz ?? redZ)) * -0.15, -0.06, 0.06);
  blueCar.rotation.x = THREE.MathUtils.clamp((blueZ - (blueCar.userData.bz ?? blueZ)) * -0.15, -0.06, 0.06);
  redCar.userData.pz = redZ;
  blueCar.userData.bz = blueZ;

  updateCamera(raceT, redZ, blueZ);
  updateHUD(raceT, redZ, blueZ);

  renderer.render(scene, camera);
}
animate();

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});
</script>
</body>
</html>
```
